def pad_to(frame, length):
    # extend payload area (before FCS) to reach total length, recompute FCS
    body, _fcs = frame[:-4], frame[-4:]
    if len(body) < length - 4:
        et_end = 18 if body[12:14] == b"\x81\x00" else 14
        body = body[:et_end] + b"\x00" * (length - 4 - et_end) + body[et_end:]
    return body + (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")

